<?php
namespace App\Http\Controllers;
use App\Models\User;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Storage;
use Illuminate\Validation\Rule;
class TeacherOperationsController extends Controller {
 private function school(Request $r):int {abort_unless($r->user()?->school_id,403,'School assignment required');return (int)$r->user()->school_id;}
 private function admin(Request $r):bool{return $r->user()->hasAnyRole(['Admin','Super Admin']);}
 private function requireAdmin(Request $r):void{abort_unless($this->admin($r),403);}
 public function gallery(Request $r){$images=DB::table('teacher_gallery_images')->where('school_id',$this->school($r))->latest('id')->paginate(18);return view('teacher.operations.gallery',compact('images'));}
 public function upload(Request $r){$data=$r->validate(['title'=>'required|string|max:255','caption'=>'nullable|string|max:500','image'=>'required|image|mimes:jpg,jpeg,png,webp|max:4096']);$path=$r->file('image')->store('teacher-gallery/'.$this->school($r),'public');DB::table('teacher_gallery_images')->insert(['school_id'=>$this->school($r),'uploaded_by'=>$r->user()->id,'title'=>$data['title'],'caption'=>$data['caption']??null,'image_path'=>$path,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Image uploaded');}
 public function deleteImage(Request $r,int $id){$row=DB::table('teacher_gallery_images')->where('school_id',$this->school($r))->where('id',$id)->first();abort_unless($row,404);abort_unless($this->admin($r)||(int)$row->uploaded_by===(int)$r->user()->id,403);DB::table('teacher_gallery_images')->where('id',$id)->delete();Storage::disk('public')->delete($row->image_path);return back()->with('success','Image deleted');}
 public function inventory(Request $r){$school=$this->school($r);$items=DB::table('teacher_inventory_items')->where('school_id',$school)->orderBy('name')->get();$requests=DB::table('teacher_inventory_requests as q')->join('teacher_inventory_items as i','i.id','=','q.item_id')->where('q.school_id',$school)->where('i.school_id',$school)->when(!$this->admin($r),fn($q)=>$q->where('q.requested_by',$r->user()->id))->select('q.*','i.name as item_name')->orderByDesc('q.id')->paginate(20);return view('teacher.operations.inventory',compact('items','requests')+['isAdmin'=>$this->admin($r)]);}
 public function addItem(Request $r){$this->requireAdmin($r);$data=$r->validate(['name'=>'required|string|max:255','sku'=>'nullable|string|max:80','quantity'=>'required|integer|min:0|max:1000000','unit'=>'required|string|max:30']);DB::table('teacher_inventory_items')->insert(['school_id'=>$this->school($r),...$data,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Inventory item added');}
 public function requestItem(Request $r){$school=$this->school($r);$data=$r->validate(['item_id'=>['required','integer',Rule::exists('teacher_inventory_items','id')->where('school_id',$school)],'quantity'=>'required|integer|min:1|max:1000000','reason'=>'required|string|max:2000']);DB::table('teacher_inventory_requests')->insert(['school_id'=>$school,'requested_by'=>$r->user()->id,...$data,'status'=>'pending','created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Request submitted');}
 public function reviewItem(Request $r,int $id){$this->requireAdmin($r);$data=$r->validate(['decision'=>['required',Rule::in(['approved','rejected'])]]);DB::transaction(function()use($r,$id,$data){$q=DB::table('teacher_inventory_requests')->where('school_id',$this->school($r))->where('id',$id)->lockForUpdate()->first();abort_unless($q,404);abort_unless($q->status==='pending',422,'Already reviewed');abort_if((int)$q->requested_by===(int)$r->user()->id,403,'Cannot approve own request');if($data['decision']==='approved'){$item=DB::table('teacher_inventory_items')->where('school_id',$this->school($r))->where('id',$q->item_id)->lockForUpdate()->first();abort_unless($item && $item->quantity>=$q->quantity,422,'Insufficient inventory');DB::table('teacher_inventory_items')->where('id',$item->id)->decrement('quantity',$q->quantity);}DB::table('teacher_inventory_requests')->where('id',$id)->update(['status'=>$data['decision'],'reviewed_by'=>$r->user()->id,'reviewed_at'=>now(),'updated_at'=>now()]);});return back()->with('success','Inventory request reviewed');}
 public function tickets(Request $r){$school=$this->school($r);$tickets=DB::table('teacher_support_tickets')->where('school_id',$school)->when(!$this->admin($r),fn($q)=>$q->where(function($q)use($r){$q->where('created_by',$r->user()->id)->orWhere('assigned_to',$r->user()->id);}))->latest('id')->paginate(20);$users=$this->admin($r)?User::where('school_id',$school)->orderBy('name')->get(['id','name']):collect();return view('teacher.operations.tickets',compact('tickets','users')+['isAdmin'=>$this->admin($r)]);}
 public function createTicket(Request $r){$data=$r->validate(['title'=>'required|string|max:255','description'=>'required|string|max:5000','priority'=>['required',Rule::in(['low','normal','high'])]]);DB::table('teacher_support_tickets')->insert(['school_id'=>$this->school($r),'created_by'=>$r->user()->id,...$data,'status'=>'open','created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Ticket created');}
 public function updateTicket(Request $r,int $id){$this->requireAdmin($r);$school=$this->school($r);$data=$r->validate(['status'=>['required',Rule::in(['open','in_progress','resolved','closed'])],'assigned_to'=>['nullable','integer',Rule::exists('users','id')->where('school_id',$school)]]);$changed=DB::table('teacher_support_tickets')->where('school_id',$school)->where('id',$id)->update(['status'=>$data['status'],'assigned_to'=>$data['assigned_to']??null,'updated_at'=>now()]);abort_unless($changed,404);return back()->with('success','Ticket updated');}
}
